const d = p.data; const out = d.start.map((s, i) => ({start: s, value: d.value[i], p10: d.p10[i], p90: d.p90[i], source: d.source[i]}));
msg.confirmed = out.filter(x => x.source === 'ACTUAL_PSTRYK');
